"""Cuaderno del estudiante, 2.º medio Lengua y Literatura, OA 21 (diálogo constructivo) y OA 22 (exposición investigada).

Los diálogos, exposiciones, datos y fuentes son originales e inventados («de ejemplo»); cada ejercicio trae escritos el guion y los datos que necesita.
Nota: los títulos de las clases del repositorio ordenan cada OA en etapas generales (escuchar o preparar, reconstruir, modelar,
ensayar, comunicar, responder); este cuaderno las sigue y reparte entre ellas los contenidos del OA oficial.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA21 = "LE2M OA 21"
OA22 = "LE2M OA 22"
E = ex

MAT = "Este cuaderno, lápiz y los textos y datos escritos en cada ejercicio. No necesitas libros especiales ni internet."

_N = [0]


def Q(stem, right, wrongs, why):
    """Pregunta de alternativas: la correcta rota de posición; las incorrectas son errores plausibles."""
    _N[0] += 1
    opts = list(wrongs)
    opts.insert(_N[0] % (len(wrongs) + 1), right)
    letters = "ABCD"
    body = " ".join(f"{letters[i]}) {o}" for i, o in enumerate(opts))
    return ex(f"{stem} {body}", f"{letters[opts.index(right)]}) {right}", why)


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend, materials=MAT):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


